         r = t % 3
         if a+1 >= p and not r == 0:
             u += 1
         elif a >= p and r == 0:
             u += 1
         elif a > 0 and a+1 >= p and r == 0:
             s += 1
         elif a+2 >= p and r == 2:
             s += 1

     return min(num_surprises, s) + u



